sn_aia_agent.context_processing_script:
/*
 * Context Processing Script for Look Up Lending Application AI Agent
 * Automatically runs LendingCustomerLookup when a phone number is detected
 * Exposes Contact, Account, Case, and Task SYS IDs directly on triggerContext
 */
(function(task, user_utterance, agent_id, context) {
    var trigCtx = context?.triggerContext || {};
    var pageCtx = context?.pageContext || {};

    try {
        var phone = trigCtx.caller_phone || trigCtx.phone || trigCtx.phone_number || "";
        if (!phone && user_utterance) {
            var match = (user_utterance + "").match(/\+?[0-9][0-9\s\-\(\)]{6,15}[0-9]/);
            if (match) {
                phone = match[0];
            }
        }

        if (phone) {
            var lookup = new x_snc_pab_ee_tkit.LendingCustomerLookup();
            var lookupRes = lookup.lookupByPhone(phone);
            trigCtx.customer_lookup = lookupRes;
            if (lookupRes.found) {
                trigCtx.customer_type = lookupRes.customer_type;
                trigCtx.customer_sys_id = lookupRes.customer_sys_id;
                trigCtx.contact_sys_id = lookupRes.contact_sys_id;
                trigCtx.consumer_sys_id = lookupRes.consumer_sys_id;
                trigCtx.account_sys_id = lookupRes.account_sys_id;
                trigCtx.case_sys_ids = lookupRes.case_sys_ids;
                trigCtx.task_sys_ids = lookupRes.task_sys_ids;
                trigCtx.customer_details = lookupRes.customer_details;
                trigCtx.calling_from_account = lookupRes.calling_from_account;
                trigCtx.financial_accounts = lookupRes.financial_accounts;
                trigCtx.open_cases = lookupRes.open_cases;
                trigCtx.customer_visible_tasks = lookupRes.customer_visible_tasks;
            }
        }
    } catch (e) {
        gs.error("Look Up Lending Application context_processing_script error: " + e.message);
    }

    return {
        pageContext: pageCtx,
        triggerContext: trigCtx
    };
})(task, user_utterance, agent_id, context);
